def _classify_alter(stmt: exp.Alter, raw_sql: str) -> Action:
    if str(stmt.args.get("kind") or "").upper() != "TABLE" or not _only_args(stmt, {"this", "exists", "actions", "only", "kind"}):
        return Action(raw_sql, "other", raw_sql=raw_sql)
    actions = stmt.args.get("actions") or []
    if len(actions) != 1:
        return Action(raw_sql, "other", raw_sql=raw_sql)
    act = actions[0]
    table = _name(stmt.args.get("this"))

    if isinstance(act, exp.Drop) and str(act.args.get("kind") or "").upper() == "COLUMN":
        cols = act.args.get("tables") or act.args.get("expressions") or []
        if _only_args(act, {"exists", "tables", "expressions", "kind"}) and len(cols) == 1:
            return Action(_canon(stmt), "drop_column", table, _name(cols[0]), raw_sql=raw_sql)
        return Action(raw_sql, "other", raw_sql=raw_sql)

    if isinstance(act, exp.RenameColumn):
        if _only_args(act, {"this", "to", "exists"}):
            return Action(_canon(stmt), "rename_column", table, _name(act.args.get("this")),
                          new_name=_name(act.args.get("to")), raw_sql=raw_sql)
        return Action(raw_sql, "other", raw_sql=raw_sql)

    if isinstance(act, exp.AlterColumn):
        if _only_args(act, {"this", "dtype"}) and act.args.get("dtype") is not None:
            return Action(_canon(stmt), "alter_type", table, _name(act.args.get("this")), raw_sql=raw_sql)
        return Action(raw_sql, "other", raw_sql=raw_sql)

    return Action(raw_sql, "other", raw_sql=raw_sql)

